#!/usr/bin/env node
// Подтягивает golden-эталон examples/ к шаблонам плагина: engine-блоки charter, team-lead.md,
// ролей и памяти заменяются одноимёнными блоками шаблона, копии .claude/reference/ и
// .claude/bin|hooks/ — файлами плагина под шапкой с версией эталона (штамп его charter).
// Проектный текст вне блоков и сам штамп не трогаются: это то же слияние, что делает
// /beerpowers:update, только по эталону. Проверяет результат check_golden.py.
//
//   node .github/scripts/sync_golden.mjs          — переписать отставшее, напечатать что
//   node .github/scripts/sync_golden.mjs --check  — только перечислить, выход 1 при расхождении
import fs from 'node:fs'
import path from 'node:path'

const TEMPLATES = 'plugins/beerpowers/templates'
const REFERENCE = 'plugins/beerpowers/reference'
const COPIED_REFERENCE = ['hooks.md', 'tasks-layout.md', 'worktrees.md', 'git-flow.md']
const VERSION_TOKEN = '{{BEERPOWERS_VERSION}}'
const BLOCK = /<!-- beerpowers:engine ([a-z0-9-]+)(?: if=[^ ]+)? -->\n[\s\S]*?<!-- \/beerpowers:engine -->/g
const STAMP = /generated-by: beerpowers v(\d+\.\d+\.\d+) · mode: plugin-linked/
const check = process.argv.includes('--check')

const read = (p) => fs.readFileSync(p, 'utf8')
const walk = (dir, keep) => !fs.existsSync(dir) ? [] : fs.readdirSync(dir, { withFileTypes: true }).flatMap((e) => {
  const p = path.join(dir, e.name)
  return e.isDirectory() ? walk(p, keep) : keep(p) ? [p] : []
})

function templateFor(root, file) {
  const parts = path.relative(root, file).split(path.sep)
  if (parts[0] === '.claude' && parts[1] === 'team-charter.md') return `${TEMPLATES}/charter/team-charter.md`
  if (parts[0] === '.claude' && parts[1] === 'team-lead.md') return `${TEMPLATES}/charter/team-lead.md`
  if (parts[0] === '.claude' && parts[1] === 'agents') return `${TEMPLATES}/roles/${parts[2]}`
  if (parts[0] === 'memory') return path.join(TEMPLATES, 'memory', ...parts.slice(1))
  return null
}

const changed = []
const update = (file, before, after) => {
  if (before === after) return
  changed.push(file)
  if (!check) fs.writeFileSync(file, after)
}

const charters = walk('examples', (p) => p.endsWith(path.join('.claude', 'team-charter.md')))
if (!charters.length) {
  console.error('в examples/ нет ни одного charter')
  process.exit(1)
}
for (const charter of charters) {
  const root = path.dirname(path.dirname(charter))
  const version = (read(charter).match(STAMP) || [])[1]
  if (!version) {
    console.error(`${charter}: нет штампа generated-by — версию эталона взять неоткуда`)
    process.exit(1)
  }

  const files = [charter, path.join(root, '.claude', 'team-lead.md'),
    ...walk(path.join(root, '.claude', 'agents'), (p) => p.endsWith('.md')),
    ...walk(path.join(root, 'memory'), (p) => p.endsWith('.md'))]
  for (const file of files) {
    if (!fs.existsSync(file)) continue
    const template = templateFor(root, file)
    if (!template || !fs.existsSync(template)) continue
    const blocks = new Map([...read(template).matchAll(BLOCK)].map((m) => [m[1], m[0]]))
    const text = read(file)
    update(file, text, text.replace(BLOCK, (whole, name) => blocks.get(name) ?? whole))
  }

  for (const name of COPIED_REFERENCE) {
    const copy = path.join(root, '.claude', 'reference', name)
    if (!fs.existsSync(copy)) continue
    const head = `<!-- generated by beerpowers v${version} — не править: обновляет /beerpowers:update -->`
    update(copy, read(copy), `${head}\n${read(path.join(REFERENCE, name))}`)
  }
  for (const kind of ['bin', 'hooks']) {
    for (const copy of walk(path.join(root, '.claude', kind), () => true)) {
      const text = read(copy)
      if (!text.split('\n').slice(0, 2).join('\n').includes('generated by beerpowers')) continue
      const template = path.join(TEMPLATES, kind, path.relative(path.join(root, '.claude', kind), copy))
      if (fs.existsSync(template)) update(copy, text, read(template).replaceAll(VERSION_TOKEN, version))
    }
  }
}

for (const file of changed) console.log(`${check ? 'отстал' : 'обновлён'}: ${file}`)
if (!changed.length) console.log('эталон совпадает с шаблонами плагина')
process.exit(check && changed.length ? 1 : 0)
